/**
 * Component: Enhanced Modern Navbar
 * Author: @rathanak-phan (https://tailwindflex.com/@rathanak-phan)
 * Source: https://tailwindflex.com/@rathanak-phan/enhanced-modern-navbar
 * Attribution: Créé par @rathanak-phan sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function EnhancedModernNavbar() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Enhanced Navbar</title>

  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
  <style>
    .glass-effect {
      background: rgba(55, 65, 81, 0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid rgba(255, 255, 255, 0.1);
    }

    .nav-link {
      position: relative;
      transition: all 0.3s ease;
    }

    .nav-link::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: linear-gradient(90deg, #10b981, #3b82f6);
      transition: width 0.3s ease;
    }

    .nav-link:hover::after {
      width: 100%;
    }

    .nav-link:hover {
      color: #10b981;
      transform: translateY(-2px);
    }

    .logo-glow {
      filter: drop-shadow(0 0 8px rgba(16, 185, 129, 0.3));
    }

    .mobile-menu-enter {
      animation: slideDown 0.3s ease-out forwards;
    }

    .mobile-menu-exit {
      animation: slideUp 0.3s ease-out forwards;
    }

    @keyframes slideDown {
      from {
        opacity: 0;
        transform: translateY(-20px);
      }

      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes slideUp {
      from {
        opacity: 1;
        transform: translateY(0);
      }

      to {
        opacity: 0;
        transform: translateY(-20px);
      }
    }

    .btn-gradient {
      background: linear-gradient(135deg, #3b82f6, #1d4ed8);
      transition: all 0.3s ease;
      box-shadow: 0 4px 15px rgba(59, 130, 246, 0.3);
    }

    .btn-gradient:hover {
      background: linear-gradient(135deg, #2563eb, #1e40af);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(59, 130, 246, 0.4);
    }

    .user-icon {
      transition: all 0.3s ease;
    }

    .user-icon:hover {
      color: #10b981;
      transform: scale(1.1);
    }

    .hamburger-line {
      display: block;
      width: 25px;
      height: 3px;
      background-color: white;
      margin: 5px 0;
      transition: 0.3s;
      border-radius: 2px;
    }

    .hamburger-active .hamburger-line:nth-child(1) {
      transform: rotate(-45deg) translate(-5px, 6px);
    }

    .hamburger-active .hamburger-line:nth-child(2) {
      opacity: 0;
    }

    .hamburger-active .hamburger-line:nth-child(3) {
      transform: rotate(45deg) translate(-5px, -6px);
    }

    .mobile-nav-item {
      transition: all 0.3s ease;
      border-left: 4px solid transparent;
    }

    .mobile-nav-item:hover {
      background: rgba(16, 185, 129, 0.1);
      border-left-color: #10b981;
      transform: translateX(8px);
    }
  </style>
</head>

<body class="bg-gray-100 min-h-screen">
  <!-- Navbar -->
  <nav class="glass-effect fixed top-0 left-0 w-full z-50 transition-all duration-300">
    <div class="flex justify-between items-center h-16 md:h-20 lg:h-24 px-5 sm:px-10 lg:px-20 text-white">
      <!-- Logo -->
      <a href="#" class="text-2xl lg:text-3xl flex items-center gap-3 font-serif logo-glow group">
        <i class="fa-solid fa-shop text-green-500 transition-all duration-300 group-hover:rotate-12 group-hover:scale-110"></i>
        <span class="font-bold bg-gradient-to-r from-green-400 to-blue-500 bg-clip-text text-transparent">LoGo</span>
      </a>

      <!-- Navbar Links (Desktop) -->
      <ul class="hidden md:flex gap-8 text-lg font-medium">
        <li><a href="/" class="nav-link">Home</a></li>
        <li><a href="/shop" class="nav-link">Shop</a></li>
        <li><a href="/about" class="nav-link">About</a></li>
        <li><a href="/contact" class="nav-link">Contact</a></li>
      </ul>

      <!-- Actions -->
      <div class="flex items-center gap-5">
        <!-- User Icon -->
        <i class="fa-solid fa-circle-user text-2xl lg:text-3xl cursor-pointer user-icon"></i>

        <!-- Get Started Button (Desktop) -->
        <button class="hidden md:flex btn-gradient text-lg px-6 py-2 rounded-full font-semibold">
                    Get Started
                </button>

        <!-- Mobile Hamburger Menu -->
        <button class="md:hidden cursor-pointer hamburger-btn">
                    <span class="hamburger-line"></span>
                    <span class="hamburger-line"></span>
                    <span class="hamburger-line"></span>
                </button>
      </div>
    </div>

    <!-- Mobile Dropdown Menu -->
    <div id="mobileMenu" class="md:hidden bg-gray-800/95 backdrop-blur-md text-white hidden">
      <div class="p-5 space-y-2">
        <a href="/" class="mobile-nav-item block py-3 px-4 rounded-lg font-medium">
          <i class="fa-solid fa-home mr-3 text-green-500"></i>Home
        </a>
        <a href="/shop" class="mobile-nav-item block py-3 px-4 rounded-lg font-medium">
          <i class="fa-solid fa-shopping-bag mr-3 text-blue-500"></i>Shop
        </a>
        <a href="/about" class="mobile-nav-item block py-3 px-4 rounded-lg font-medium">
          <i class="fa-solid fa-info-circle mr-3 text-purple-500"></i>About
        </a>
        <a href="/contact" class="mobile-nav-item block py-3 px-4 rounded-lg font-medium">
          <i class="fa-solid fa-envelope mr-3 text-orange-500"></i>Contact
        </a>
        <div class="pt-4 border-t border-gray-600">
          <button class="btn-gradient w-full text-lg px-6 py-3 rounded-full font-semibold">
                        Get Started
                    </button>
        </div>
      </div>
    </div>
  </nav>

  <!-- Demo Content -->
  <div class="pt-32 px-5 text-center">
    <h1 class="text-4xl font-bold text-gray-800 mb-4">Enhanced Navbar Demo</h1>
    <p class="text-gray-600 text-lg">Scroll down to see the navbar in action with glassmorphism effect</p>

    <div class="mt-20 space-y-8">
      <div
        class="h-96 bg-gradient-to-r from-blue-400 to-purple-500 rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
        Demo Section 1
      </div>
      <div
        class="h-96 bg-gradient-to-r from-green-400 to-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
        Demo Section 2
      </div>
      <div
        class="h-96 bg-gradient-to-r from-purple-400 to-pink-500 rounded-2xl flex items-center justify-center text-white text-2xl font-bold">
        Demo Section 3
      </div>
    </div>
  </div>


</body>

</html>" }} />
  );
}
